//! 🧪️ Original PNG ownership matches independent decoding and actual allocator receipts.
use super::*;
use crate::retirement::tests::{drain,observed};
fn rows()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
fn input(row:&serde_json::Value)->PngDecodeInput{PngDecodeInput{data:serde_json::from_value(row["data"].clone()).unwrap(),max_pixels:row["maxPixels"].as_u64().unwrap()as usize,max_bytes:row["maxBytes"].as_u64().unwrap()as usize,max_chunks:row["maxChunks"].as_u64().unwrap()as usize}}
fn job(input:PngDecodeInput)->PngDecodeJob{PngDecodeJob::new(input).unwrap()}
fn grant(job:&PngDecodeJob)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:job.next_copy_byte_demand().unwrap(),maximum_capacity_bytes:job.next_capacity_byte_demand().unwrap(),maximum_release_bytes:0,maximum_depth:1}}
fn finish(job:&mut PngDecodeJob,items:usize)->Result<(),PngDecodeError>{let(mut work,mut bytes,mut pixels)=(0,0,0);for _ in 0..2000000{let grant=RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:items*131072,maximum_capacity_bytes:67108864,maximum_release_bytes:0,maximum_depth:1};let(progress,receipt)=job.advance(grant)?;assert!(receipt.fits(grant));assert!(progress.work-work<=items as u64);assert!(progress.bytes>=bytes);assert!(progress.pixels>=pixels);work=progress.work;bytes=progress.bytes;pixels=progress.pixels;if progress.done{return Ok(());}}panic!("PNG job did not finish")}
fn output(job:&mut PngDecodeJob)->RasterImage{job.take_result(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:size_of::<RasterImage>(),maximum_depth:1,..Default::default()}).unwrap().unwrap().0}
fn oracle(data:&[u8])->RasterImage{let mut decoder=png::Decoder::new(std::io::Cursor::new(data));decoder.set_transformations(png::Transformations::EXPAND|png::Transformations::STRIP_16);let mut reader=decoder.read_info().unwrap();let mut bytes=vec![0;reader.output_buffer_size()];let info=reader.next_frame(&mut bytes).unwrap();let mut out=Vec::new();for pixel in bytes[..info.buffer_size()].chunks(info.color_type.samples()){match info.color_type{png::ColorType::Grayscale=>out.extend_from_slice(&[pixel[0],pixel[0],pixel[0],255]),png::ColorType::Rgb=>out.extend_from_slice(&[pixel[0],pixel[1],pixel[2],255]),png::ColorType::GrayscaleAlpha=>out.extend_from_slice(&[pixel[0],pixel[0],pixel[0],pixel[1]]),png::ColorType::Rgba=>out.extend_from_slice(pixel),_=>panic!("oracle did not expand palette")}}RasterImage{width:info.width,height:info.height,pixels:out}}
#[test]
fn png_decode_shared_all_depths_filters_interlace_and_huffman_under_grants(){
 let rows=rows();for row in rows.as_array().unwrap(){let expected:Vec<u8>=serde_json::from_value(row["expected"]["pixels"].clone()).unwrap();let reference=oracle(&input(&row["input"]).data);assert_eq!(reference.pixels,expected,"{} independent PNG oracle",row["name"]);for items in [1,7,4096]{let mut job=job(input(&row["input"]));finish(&mut job,items).unwrap();assert_eq!(job.result().unwrap().pixels,expected);let image=output(&mut job);assert_eq!((image.width,image.height),(reference.width,reference.height));drain(job);drain(image);}}
 eprintln!("[DEBUG] Native PNG all shared depth/filter/interlace/Huffman fixtures matched independent decoder through real grants");
}
#[test]
fn png_decode_malformed_originals_refuse_private_output(){
 let rows:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/⚠️invalid/🔣️.json")).unwrap();for row in rows.as_array().unwrap(){match PngDecodeJob::new(input(&row["input"])){Ok(mut job)=>{assert!(finish(&mut job,7).is_err(),"{}",row["name"]);assert!(job.result().is_err());drain(job);},Err((_,original))=>{drain(original);}}}
 eprintln!("[DEBUG] Native malformed PNG sources retained their real source and private child owners");
}
#[test]
fn png_decode_original_funding_and_cancellation_match_actual_allocator(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🎟️funding.json")).unwrap();let rows=rows();let row=&rows[fixture["fixtureCase"].as_u64().unwrap()as usize];let original=input(&row["input"]);let reference=oracle(&original.data);let mut decoder=job(original);let pointer=decoder.source().as_ptr();let original_capacity=decoder.source.capacity();let mut born=0;let mut turns=0;
 while !decoder.progress().done{let funded=grant(&decoder);let before=decoder.progress();for row in fixture["cases"].as_array().unwrap(){let mut denied=funded;let demand=match row["axis"].as_str().unwrap(){"maximumItems"=>{denied.maximum_items=0;1},"maximumCopyBytes"=>{denied.maximum_copy_bytes=funded.maximum_copy_bytes.saturating_sub(1);funded.maximum_copy_bytes},"maximumCapacityBytes"=>{denied.maximum_capacity_bytes=funded.maximum_capacity_bytes.saturating_sub(1);funded.maximum_capacity_bytes},"releaseForCapacity"=>{denied.maximum_capacity_bytes=0;denied.maximum_release_bytes=4096;funded.maximum_capacity_bytes},"maximumDepth"=>{denied.maximum_depth=0;1},"exact"=>continue,_=>unreachable!()};if demand==0{continue;}let(result,physical)=observed(||decoder.advance(denied).unwrap());assert_eq!(physical,(0,0));assert_eq!(result,(before,Default::default()));assert_eq!(decoder.source().as_ptr(),pointer);}
  let((_,receipt),physical)=observed(||decoder.advance(funded).unwrap());assert!(receipt.fits(funded));assert_eq!(physical,(receipt.retained_capacity_bytes,0));born+=physical.0;turns+=1;assert!(turns<2000000);
 }
 assert_eq!(decoder.result().unwrap().pixels,reference.pixels);let funded=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:size_of::<RasterImage>(),maximum_depth:1,..Default::default()};assert!(observed(||decoder.take_result(RetainedCloneGrant{maximum_copy_bytes:funded.maximum_copy_bytes-1,..funded}).unwrap()).0.is_none());let image=decoder.take_result(funded).unwrap().unwrap().0;let(a,r)=drain(decoder);let(a2,r2)=drain(image);assert_eq!(original_capacity+born+a+a2,r+r2);
 for stop in fixture["interruptions"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){let source=input(&row["input"]);let original=source.data.capacity();let mut decoder=job(source);let pointer=decoder.source().as_ptr();let mut born=0;for _ in 0..stop{if decoder.progress().done{break;}let funded=grant(&decoder);let(_,physical)=observed(||decoder.advance(funded).unwrap());born+=physical.0;}assert_eq!(observed(||decoder.cancel()).1,(0,0));assert_eq!(decoder.source().as_ptr(),pointer);assert_eq!(decoder.result().unwrap_err(),PngDecodeError::Cancelled);let(a,r)=drain(decoder);assert_eq!(original+born+a,r);}
 let mut source=input(&row["input"]);source.max_pixels=0;let pointer=source.data.as_ptr();let original=source.data.capacity();let(result,physical)=observed(||PngDecodeJob::new(source));assert_eq!(physical,(0,0));let(_,source)=match result{Err(value)=>value,Ok(_)=>panic!("invalid PNG admitted")};assert_eq!(source.data.as_ptr(),pointer);let(a,r)=drain(source);assert_eq!(original+a,r);
 eprintln!("[DEBUG] Native PNG original6axis cases at{turns}turns,6cancellations,constructor preservation and exact source/born/closure allocator conservation");
}
#[test]
fn png_decode_truncated_fixture_prefixes_never_publish(){
 let rows=rows();let mut prefixes=0;for row in rows.as_array().unwrap(){let source=input(&row["input"]);for length in 0..source.data.len(){let mut truncated=source.clone();truncated.data=source.data[..length].to_vec();match PngDecodeJob::new(truncated){Ok(mut job)=>{assert!(finish(&mut job,4096).is_err(),"{} prefix{length}",row["name"]);drain(job);},Err((_,original))=>{drain(original);}}prefixes+=1;}}
 eprintln!("[DEBUG] Native PNG all{prefixes}truncated originals refused publication and closed exact owners");
}